  // Runs `command` in the Console and waits up to `budget_ms` for `wanted` in what followed it.
  QString selfcheck_console(const QString& command, const QString& wanted, int budget_ms) {
    show_page(vm::WorkspacePage::explorer);
    QApplication::processEvents();
    if (shell_command_ == nullptr || shell_output_ == nullptr) {
      return QStringLiteral("the Console tab was never built");
    }
    const qsizetype before = console_transcript_.size();
    shell_command_->setText(command);
    console_run_command();
    QElapsedTimer timer;
    timer.start();
    while (timer.elapsed() < budget_ms &&
           (wanted.isEmpty() || !console_transcript_.mid(before).contains(wanted))) {
      QApplication::processEvents(QEventLoop::AllEvents, 50);
      std::this_thread::sleep_for(std::chrono::milliseconds(20));
    }
    return console_transcript_.mid(before);
  }

  bool selfcheck_console_select_shell(const QString& program) {
    show_page(vm::WorkspacePage::explorer);
    QApplication::processEvents();
    if (shell_program_ == nullptr) {
      return false;
    }
    const int index = shell_program_->findText(program);
    if (index < 0) {
      return false;
    }
    shell_program_->setCurrentIndex(index);
    return true;
  }

  // Stop, timed: the milliseconds it took, and whether the session is gone with its note shown and
  // Stop greyed out again.
  std::pair<qint64, bool> selfcheck_console_stop() {
    QElapsedTimer timer;
    timer.start();
    stop_local_shell();
    const qint64 taken = timer.elapsed();
    const bool ended =
        !local_shell_ &&
        console_transcript_.contains(
            QStringLiteral("[local session ended - the next command starts a new one]")) &&
        console_stop_ != nullptr && !console_stop_->isEnabled();
    return {taken, ended};
  }

