  // A Customer / Lab board in a view of this size, as Home places it: how many sections show
  // compact to fit, and the fit as measured.
  std::pair<int, QString> selfcheck_lab_board_fit(int width, int height) const {
    QScrollArea area;
    area.setWidgetResizable(true);
    area.setHorizontalScrollBarPolicy(Qt::ScrollBarAlwaysOff);
    auto* body = new QWidget();
    auto* body_layout = new QVBoxLayout(body);
    body_layout->setContentsMargins(0, 0, 12, 0);
    auto* view = new sat_qt::BoardView([](int) {});
    body_layout->addWidget(view);
    body_layout->addStretch(1);
    area.setWidget(body);
    view->fit_to(area.viewport());
    auto [groups, chips] = board_widgets(vm::lab_home(vm::LabBoardInput{}));
    view->set_content(std::move(groups), std::move(chips), {});
    area.resize(width, height);
    area.show();
    QApplication::processEvents();
    return {view->compact_to_fit(), view->fit_state()};
  }
  // The rows a card grid on the page in view spans, or -1 when the page shows no card grid.
  int selfcheck_card_grid_rows() const {
    for (QGridLayout* grid : findChildren<QGridLayout*>()) {
      if (!grid->property("satCardColumns").isValid() || grid->parentWidget() == nullptr ||
          !grid->parentWidget()->isVisible() || grid->count() < 4) {
        continue;
      }
      int rows = 0;
      for (int index = 0; index < grid->count(); ++index) {
        int row = 0;
        int column = 0;
        int row_span = 0;
        int column_span = 0;
        grid->getItemPosition(index, &row, &column, &row_span, &column_span);
        rows = std::max(rows, row + 1);
      }
      return rows;
    }
    return -1;
  }
