public:
#ifdef SUPPORT_ASSIST_UI_SELFCHECK
  // Full screen, then the button's click: whether it showed, and whether the window came back.
  std::pair<bool, bool> selfcheck_exit_full_screen() {
    setWindowState(windowState() | Qt::WindowFullScreen);
    QCoreApplication::processEvents();
    const bool shown = exit_full_screen_ != nullptr && !exit_full_screen_->isHidden();
    if (exit_full_screen_ != nullptr)
      exit_full_screen_->click();
    QCoreApplication::processEvents();
    const bool back = (windowState() & Qt::WindowFullScreen) == 0 && exit_full_screen_ != nullptr &&
                      exit_full_screen_->isHidden();
    setWindowState(windowState() & ~Qt::WindowFullScreen);
    return {shown, back};
  }
#endif

